<script setup lang="ts">
import { useApi } from '~/composables/useApi';

import type { User } from '~/types/api'
import {dateTR} from '~/utils/format'
const api=useApi();const rows=ref<User[]>([]);const state=ref<'loading'|'error'|'success'>('loading');const error=ref('');const inviteCode=ref('');const codeVisible=ref(false);const codeError=ref('');const codeLoading=ref(false);const deleting=ref<number|null>(null);const deleteError=ref('')
async function removeUser(u:User){if(!confirm(`${u.full_name} hesabını silmek istediğinize emin misiniz? Bu işlem geri alınamaz.`))return;deleteError.value='';deleting.value=u.id;try{await api.deleteUser(u.id);rows.value=rows.value.filter(x=>x.id!==u.id)}catch(e){deleteError.value=e instanceof Error?e.message:'Kullanıcı silinemedi.'}finally{deleting.value=null}}
async function copyInviteCode(){try{await navigator.clipboard.writeText(inviteCode.value)}catch{codeError.value='Panoya kopyalanamadı. Kodu elle seçip kopyalayabilirsiniz.'}}
async function loadInviteCode(){codeError.value='';codeLoading.value=true;try{const result=await api.request<{registration_code:string}>('/auth/office-registration-code');inviteCode.value=result.registration_code;codeVisible.value=true}catch(e){codeError.value=e instanceof Error?e.message:'Kayıt kodu alınamadı.'}finally{codeLoading.value=false}}
async function load(){state.value='loading';try{rows.value=await api.users({limit:100,offset:0});state.value='success'}catch(e){error.value=e instanceof Error?e.message:'Kullanıcılar alınamadı.';state.value='error'}}
await load()
</script>
<template><div class="page-heading"><div><p class="eyebrow">YÖNETİM</p><h1>Kullanıcı yönetimi</h1><p>Kayıtlı kullanıcıların rollerini ve durumlarını görüntüleyin.</p></div><button class="button button-secondary" @click="load">↻ Yenile</button></div><section class="panel invite-panel"><div class="panel-header"><div><h2>Ofis davet kodu</h2><p>Yeni çalışan kayıtlarında kullanılacak kod. Yalnızca yönetici hesabı görüntüleyebilir.</p></div><button class="button button-secondary" :disabled="codeLoading" @click="loadInviteCode">{{ codeLoading ? 'Yükleniyor…' : codeVisible ? 'Kodu yenile' : 'Kodu göster' }}</button></div><div v-if="codeVisible" class="invite-code-row"><code>{{ inviteCode }}</code><button class="button button-secondary" @click="copyInviteCode">Kopyala</button><button class="button button-secondary" @click="codeVisible=false">Gizle</button></div><div v-if="codeError" class="alert alert-warning" role="alert">{{ codeError }}</div><p class="muted-note">Kod görünmüyorsa backend .env dosyasındaki OFFICE_REGISTRATION_CODE ayarını kontrol edin. Kod paylaşıldığında ofis dışındaki kişiler de kayıt olabilir; yalnızca güvenilir çalışanlarla paylaşın.</p></section><section class="panel"><div v-if="deleteError" class="alert alert-warning">{{ deleteError }}</div><div class="panel-header"><div><h2>Kullanıcılar</h2><p>API'den alınan kullanıcı kayıtları</p></div><span class="chip">{{ rows.length }} kullanıcı</span></div><StatePanel v-if="state==='loading'" state="loading"/><StatePanel v-else-if="state==='error'" state="error" :message="error" @retry="load"/><StatePanel v-else-if="!rows.length" state="empty" message="API kullanıcı kaydı döndürmedi."/><div v-else class="table-wrap"><table><thead><tr><th>Kullanıcı</th><th>Rol</th><th>Durum</th><th>Kayıt tarihi</th><th>İşlem</th></tr></thead><tbody><tr v-for="u in rows" :key="u.id"><td><div class="table-primary">{{ u.full_name }}</div><div class="table-sub">Kullanıcı #{{ u.id }}</div></td><td><span class="chip">{{ u.role==='admin'?'Yönetici':'Danışman' }}</span></td><td><span class="status-badge" :class="u.is_active?'status-active':'status-passive'">{{ u.is_active?'Aktif':'Pasif' }}</span></td><td>{{ dateTR(u.created_at) }}</td><td><button class="button button-secondary" :disabled="deleting===u.id" @click="removeUser(u)">{{ deleting===u.id?'Siliniyor…':'Hesabı sil' }}</button></td></tr></tbody></table></div></section></template>
<style scoped>.invite-panel{margin-bottom:20px}.invite-code-row{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:14px 0}.invite-code-row code{padding:12px 14px;border:1px solid var(--border,#dbe2ee);border-radius:8px;font-size:15px;flex:1;min-width:220px}.muted-note{font-size:13px;color:var(--muted,#6b7890);margin-top:12px}</style>

